## 3. CORE SENSOR FUSION ALGORITHM (C++)

```cpp
// File: src/sensor_fusion.cpp
// Description: Multi-sensor fusion for industrial vibration monitoring

#include <esp_math.h>
#include <driver/gpio.h>

// Sensor calibration constants (measured during factory QC)
const float CALIB_VIBRATION_0 = 0.0032f;   // g/√Hz reference
const float CALIB_TEMPERATURE_0 = 25.0f;   // °C baseline
const float CALIB_HUMIDITY_0 = 45.0f;      // % RH baseline

struct VibrationSample {
    uint64_t timestamp_ns;
    float acceleration_x;
    float acceleration_y;
    float acceleration_z;
    float frequency_hz;
};

struct TemperatureReading {
    uint64_t timestamp_ns;
    float temp_c;
};

struct HumidityReading {
    uint64_t timestamp_ns;
    float humidity_pct;
};

// State machine for sensor fusion
enum class FusionState { IDLE, CALIBRATING, TRACKING, ANOMALY_DETECTED };

class SensorFusionEngine {
private:
    FusionState state;

    // Kalman filter state vectors [accel_x, accel_y, accel_z, temp, hum]
    struct KalmanState {
        float x[5];           // position estimate
        float p[5][5];        // covariance matrix
        float q[5][5];        // process noise
        float r[5];           // measurement noise
    } kalman;

    // Rolling window buffers (last 60 samples)
    static const int WINDOW_SIZE = 60;
    VibrationSample vibration_buffer[WINDOW_SIZE];
    TemperatureReading temperature_buffer[WINDOW_SIZE];
    HumidityReading humidity_buffer[WINDOW_SIZE];

    // Anomaly threshold (adaptive)
    float anomaly_threshold = 3.0f;

public:
    SensorFusionEngine() : state(FusionState::IDLE) {
        // Initialize sensors
        gpio_set_pin(2, GPIO_MODE_OUTPUT_PULLUP);  // DAC1 enable
        gpio_set_pin(3, GPIO_MODE_INPUT);

        // Configure I2S audio interface for acoustic emission capture
        i2s_config_i2s0 = {
            .mode = I2S_MODE_MASTER,
            .sample_rate = 44100,
            .bits_per_sample = I2S_BITS_PER_SAMPLE_16BIT,
            .channel_format = I2S_CHANNEL_FORMAT_STANDARD_LEFT_RIGHT,
            .use_pcm = false,
            .mclk = 48000000
        };
        i2s_set_default_config(i2s_config_i2s0);
    }

    void update_sensors(const VibrationSample& vib, 
                        const TemperatureReading& temp, 
                        const HumidityReading& hum) {
        vibration_buffer[state_index++] = vib;
        if (state_index >= WINDOW_SIZE) vibration_buffer[0] = vib;

        temperature_buffer[state_index++] = temp;
        if (state_index >= WINDOW_SIZE) temperature_buffer[0] = temp;

        humidity_buffer[state_index++] = hum;
        if (state_index >= WINDOW_SIZE) humidity_buffer[0] = hum;
    }

    KalmanState run_kalman_filter() {
        if (state_index == 0) return kalman; // Not enough data

        // Extract latest sample
        VibrationSample latest = vibration_buffer[state_index - 1];
        TemperatureReading latest_temp = temperature_buffer[state_index - 1];
        HumidityReading latest_hum = humidity_buffer[state_index - 1];

        // Update Kalman filter (simplified 5-state model)
        kalman.x[0] = latest.acceleration_x;  // x = vertical acceleration proxy
        kalman.x[1] = latest.acceleration_y;
        kalman.x[2] = latest.acceleration_z;
        kalman.x[3] = latest_temp.temp_c;
        kalman.x[4] = latest_hum.humidity_pct;

        // Process noise increment
        float Q = 0.01f * (kalman.p[0][0]/100.0f); // Process variance
        kalman.p[0][0] += Q;
        kalman.p[1][1] += Q;
        kalman.p[2][2] += Q;
        kalman.p[3][3] += Q;
        kalman.p[4][4] += Q;

        // Measurement update (simplified - in production use full EKF)
        float z_accel = map(acceleration_to_g(latest.acceleration_x), 0, 10, 0, 10);
        float z_temp = latest_temp.temp_c - CALIB_TEMPERATURE_0;
        float z_hum = latest_hum.humidity_pct - CALIB_HUMIDITY_0;

        // Innovation calculation
        float y = 0;
        y += kalman.p[0][0] * (z_accel - latest.acceleration_x);
        y += kalman.p[1][1] * (z_temp - latest_temp.temp_c);
        y += kalman.p[3][3] * (z_hum - latest_hum.humidity_pct);

        // Kalman gain computation (simplified)
        float K = kalman.p[0][0] / (kalman.p[0][0] + kalman.p[1][1] + kalman.p[3][3]);

        // State correction
        kalman.x[0] -= K * y;
        kalman.x[1] -= K * y;
        kalman.x[2] -= K * y;
        kalman.x[3] -= K * y;
        kalman.x[4] -= K * y;

        return kalman;
    }

    double compute_vibration_energy() {
        double energy = 0.0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            VibrationSample s = vibration_buffer[i];
            energy += (s.acceleration_x * s.acceleration_x +
                       s.acceleration_y * s.acceleration_y +
                       s.acceleration_z * s.acceleration_z);
        }
        return energy / WINDOW_SIZE;
    }

    bool detect_anomaly() {
        if (state_index == 0) return false;

        float current_anomaly = 0.0f;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            VibrationSample s = vibration_buffer[i];
            float avg_acc = sqrt(s.acceleration_x*s.acceleration_x +
                                s.acceleration_y*s.acceleration_y +
                                s.acceleration_z*s.acceleration_z);

            // Dynamic threshold based on rolling mean
            float rolling_mean = 0.0f;
            for (int j = 0; j < WINDOW_SIZE; j++) {
                rolling_mean += vibration_buffer[j].acceleration_x*vibration_buffer[j].acceleration_x;
            }
            rolling_mean /= WINDOW_SIZE;

            float deviation = abs(avg_acc - rolling_mean) / rolling_mean;
            current_anomaly += min(deviation, 5.0f);
        }

        return current_anomaly > anomaly_threshold;
    }
};
