## 4. REAL-TIME PROCESSING LOOP (Arduino Framework)

```cpp
// File: src/main_loop.cpp
// Main control loop with task scheduling

#include <Arduino.h>
#include "sensor_fusion.h"

SensorFusionEngine fusion;

void setup() {
    Serial.begin(115200);
    while (!Serial) ; // Wait for serial connection

    // Configure global settings
    pin_mode(GPIO_NUM_2, OUTPUT);  // DAC1 enable
    pin_mode(GPIO_NUM_3, INPUT);
    pin_mode(GPIO_NUM_4, OUTPUT);  // DAC2
    pin_mode(GPIO_NUM_5, OUTPUT);  // DAC3

    // Enable Wi-Fi for telemetry
    WiFi.mode(WIFI_STA);
    delay(100);
}

void loop() {
    static unsigned long last_update = 0;
    static uint32_t cycle_count = 0;

    // Main control loop at 1 Hz resolution
    if (millis() - last_update >= 1000) {
        last_update = millis();
        cycle_count++;

        // 1. Acquire raw sensor data
        VibrationSample vib = read_vibration_sensor();
        TemperatureReading temp = read_temperature_sensor();
        HumidityReading hum = read_humidity_sensor();

        // 2. Run sensor fusion
        KalmanState k = fusion.run_kalman_filter();
        double energy = fusion.compute_vibration_energy();
        bool anomaly = fusion.detect_anomaly();

        // 3. Publish telemetry via MQTT
        publish_mqtt_message("factory/vibration", 
                            encode_json(k, energy, anomaly));

        // 4. Actuator command (if anomaly detected)
        if (anomaly) {
            send_shutdown_command();
        }

        // 5. Sleep until next cycle
        delay(1000);
    }
}

// Raw sensor reading implementations
VibrationSample read_vibration_sensor() {
    VibrationSample s;
    s.timestamp_ns = micros();
    s.acceleration_x = analogRead(AnalogPin(GPIO_NUM_4) -> AIN0) * 16384.0 / 4096.0;
    s.acceleration_y = analogRead(AnalogPin(GPIO_NUM_5) -> AIN1) * 16384.0 / 4096.0;
    s.acceleration_z = analogRead(AnalogPin(GPIO_NUM_6) -> AIN2) * 16384.0 / 4096.0;
    s.frequency_hz = calculate_dominant_frequency(vib_data());
    return s;
}

TemperatureReading read_temperature_sensor() {
    TemperatureReading t;
    t.timestamp_ns = micros();
    // Digital temperature sensor (e.g., DS18B20 over I2C)
    // Using simulated value for this log entry
    t.temp_c = 22.5f + sin(millis() * 0.001f) * 0.5f; // ~22.5°C ± 0.5°C
    return t;
}

HumidityReading read_humidity_sensor() {
    HumidityReading h;
    h.timestamp_ns = micros();
    h.humidity_pct = 48.0f + cos(millis() * 0.002f) * 10.0f; // ~48% RH
    return h;
}
