# File: tools/power_model.py
# Energy budget analysis for ESP32 sensor node

import numpy as np

def calculate_power_budget(hw_config):
    """
    Calculate total energy consumption per hour.

    Parameters:
        hw_config: dict with keys 'flash_active', 'radio_active',
                  'adc_active', 'pwm_active'
    """
    # Baseline currents (mA) from ESP32 datasheet
    I_base = {
        'idle': 5.0,      # idle mode
        'wifi_stationary': 120.0,  # Wi-Fi listening
        'wifi_transmit': 350.0,  # Full transmit burst
        'adc_read': 30.0,   # ADC sampling rate dependent
        'pwm_output': 50.0, # DAC PWM duty cycling
        'bluetooth_ble': 80.0 # BLE advertising
    }

    # Time allocation (typical operation profile)
    time_profile = {
        'idle': 70,        # 70% of time
        'wifi_listen': 15, # 15% (intermittent)
        'adc_read': 10,    # 10% (continuous sampling)
        'pwm_output': 5,   # 5% (periodic)
        'other': 0         # residual
    }

    # Energy per unit time (mAh)
    def mha(current_mA, duration_sec):
        return (current_mA * duration_sec) / 3600.0  # mAh

    total_mah = 0.0
    for hw, curr in hw_config.items():
        if curr > 0:
            total_mah += mha(curr, time_profile.get('idle', 0))

    return round(total_mah, 2)

# Example: Active monitoring mode
hw_config = {
    'flash_active': True,
    'radio_active': False,
    'adc_active': True,
    'pwm_active': True
}

print(f"Hourly power budget: {calculate_power_budget(hw_config)} mAh")
